      "contacts": [
        {
          "type": "&lt;string&gt;",
          "format": "&lt;string&gt;",
          "value": {}
        }
      ],
      "identifiers": [
        {
          "type": "local|uai|nns|ror|wikidata|scopus",
          "value": "&lt;string&gt;"
        }
      ],
      "relationships": [
        {
          "type": "member_of",
