Payload
The payload is a flat object with three top-level keys. The fields section contains all data available for the structure in the IKG graph. main_mission and secondary_missions are only present for unit type structures (research units, support units, administrative units).


JSON schema for structure events

{
  "type": "unit|institution|institution_subdivision|unit_subdivision|team",
  "event": "created|updated|deleted|unchanged",
  "fields": {
    "uid": "&lt;string&gt;",
    "national_type": "UMR|UAR|UR|IRL|UNIV|EPE|EPST|GE|COMUE|UFR|FAC|TEAM|THEME|null",
    "local_types": [
      {
        "value": "&lt;string&gt;",
        "language": "&lt;language code&gt;"
      }
    ],
    "identifiers": [
      {
        "type": "local|uai|nns|ror|wikidata|scopus",
        "value": "&lt;string&gt;"
      }
    ],
    "long_labels": [
      {
        "value": "&lt;string&gt;",
        "language": "&lt;language code&gt;"
      }
    ],
    "short_labels": [
      {
        "value": "&lt;string&gt;",
        "language": "&lt;language code&gt;"
      }
    ],
    "descriptions": [
      {
        "value": "&lt;string&gt;",
        "language": "&lt;language code&gt;"
      }
    ],
    "memberships": [
      {
        "target": "&lt;uid of the supervising or member-of organisation&gt;",
        "position": "main_supervision|associated_supervision|participating_supervision|null",
        "start_date": "YYYY-MM-DD|null",
        "end_date": "YYYY-MM-DD|null"
      }
    ],
    "parents": [
      {
        "target": "&lt;uid of the structurally containing organisation&gt;",
        "start_date": "YYYY-MM-DD|null",
        "end_date": "YYYY-MM-DD|null"
      }
    ],
    "addresses": [
